import { Injectable } from '@angular/core';
import { UploadService } from '../upload.service';
import { FileStorageService } from '../file-storage/file-storage.service';
import { bundleMDL, checkDuplicacyMDL, fileUploadMDL, sectionDetailMDL, selectedfileMDL } from '../../../interfaces/upload.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';

@Injectable({
  providedIn: 'root'
})
export class CheckDuplicacyService {
  public nCaseid: string;

  public sectionDetail: sectionDetailMDL;
  public bundle: bundleMDL;
  constructor(private upld: UploadService, private store: FileStorageService, private userStore: SecureStorageService) { }


  async checkDuplicacy(): Promise<any> {

    this.nCaseid = await this.store.getCaseId();
    this.sectionDetail = await this.store.getSectionDetail();
    this.bundle = await this.store.getBundleDetail();
    if (this.nCaseid) {
      const fileDetail: checkDuplicacyMDL = { nCaseid: this.nCaseid, nSectionid: this.sectionDetail.nSectionid, nBundleid: this.bundle.nBundleid, d: '[]', nUPid: null };
      const files: selectedfileMDL[] = await this.store.getSelectedFileStorage();




      if (files.length) {
        /*
        0 id
        1 parentid
        2 name
        3 isFolder
        4 nBundleid
        5 nParentBundleid
        6 size
        7 type
        */

        let bachJobs: selectedfileMDL[][] = this.chunkArray(files, 200);
        let finalData = [];
        let cUnicid: string = '';
        let nUPid: string= null;
        try {

          const newObj = { ...fileDetail }
          newObj.nTotal = files?.length || 0;
          await this.upld.uploadLog(newObj);

          for (let [index, x] of bachJobs.entries()) {

            const d: any = x.filter(a => (a.isFolder || (!a.isFolder && a.file))).map((e) => {
              return [e.id, e.parentId, e.name, e.isFolder, (e.parentId == 0 ? (this.bundle.nBundleid ? this.bundle.nBundleid : null) : 0), e.nParentBundleid, !e.isFolder ? e.file.size.toString() : null, !e.isFolder ? this.getFileType(e.file.name) : null]
            })

            // const d: any = x.map(({ id, parentId, name, isFolder }) => ([id, parentId, name, isFolder]));
            fileDetail.d = JSON.stringify(d);

            let res = await this.upld.checkDuplicacyBatch(fileDetail);

            if (res.msg == 1) {

              if (index == 0) {
                cUnicid = res.cUnicid;
                nUPid = res.nUPid;
              }

              const result = res.jResult ? res.jResult : [];
              fileDetail.nUPid = res.nUPid ? res.nUPid : null;
              if (result.length) {

                finalData = finalData.concat(result);

                result.forEach(e => {
                  // files.filter(a => a.parentId == e[0]).map(a => a.nParentBundleid = e[1]);
                  files.filter(a => a.parentId == e[0]).map(a => {
                    a.nParentBundleid = e[1];
                    // a.nBundleid = e[1];
                    return a;  // explicitly return the updated object
                  });
                });

              } else {
                return false;
              }

            } else {
              return false;
            }

          }

          return { finalData, cUnicid: cUnicid, nUPid: nUPid };
        } catch (error) {
          console.log('Error:', error);
          return false;
        }



        /*const d: any = files.map(({ id, parentId, name, isFolder }) => ([id, parentId, name, isFolder]));
        fileDetail.d = JSON.stringify(d);
        let res = await this.upld.checkDuplicacy(fileDetail);
        return res && res.msg == 1 ? res.jResult : false;*/
      }
    }
  }

  async isFileDuplicated(name: string, nSectionid: string, nBundleid: string): Promise<any> {

    this.nCaseid = await this.store.getCaseId();
    if (this.nCaseid) {
      const fileDetail: checkDuplicacyMDL = { nCaseid: this.nCaseid, nSectionid: nSectionid ? nSectionid : null, nBundleid: nBundleid ? nBundleid : null, d: '[]', nUPid: null };
      fileDetail.d = JSON.stringify([1, 0, name, false]);
      let res = await this.upld.checkDuplicacy(fileDetail);
      return res && res.msg == 1 ? res.jResult : false;
    }
  }


  async isDuplicated(res: any): Promise<number[]> {
    let duplicated: number[] = res.filter(a => a.length > 3);
    return duplicated;
  }

  getRandomFile() {
    return `file_${Math.floor(Math.random() * new Date().getTime())}`
  }

  getFileType(filename: string) {
    try {
      return filename.split('.').pop().toUpperCase();
    } catch (error) {
      return 'unknown';
    }

  }

  async mergeresult(res: any, flag: string, nUPid: string): Promise<fileUploadMDL[]> {
    const nUserid = await this.userStore.getUserId();
    let files: fileUploadMDL[] = [];

    let selectedFiles: selectedfileMDL[] = await this.store.getSelectedFileStorage();

    selectedFiles.map((e) => {
      if (!e.isFolder && e.file) {
        let file = res.find(a => a[0] == e.id);
        if (file && ((flag == 'I' && !file[3]) || flag != 'I')) {
          files.push({ nUPid: nUPid, nUDid: file[2], identifier: this.store.generateRandomId(e.file, nUserid), name: this.getRandomFile(), filetype: this.getFileType(e.file.name), filesize: e.file.size, cFilename: e.name, file: e.file, nBundleid: file[1], nBundledetailid: (flag == 'U' ? 0 : (file[3])), totalChunks: Math.ceil(e.file.size / this.store.maxChunkSize), cStatus: 'P' });
        }
      }
    })
    return files;
  }


  async createStructure(file: File, nBundledetailid: string, nUDid: string, nUPid: string): Promise<fileUploadMDL> {
    const nUserid = await this.userStore.getUserId();
    return { nUPid: nUPid, nUDid: nUDid, identifier: this.store.generateRandomId(file, nUserid), name: this.getRandomFile(), filetype: this.getFileType(file.name), filesize: file.size, cFilename: file.name, file: file, nBundleid: null, nBundledetailid: nBundledetailid ? nBundledetailid : null, totalChunks: Math.ceil(file.size / this.store.maxChunkSize), cStatus: 'P' };
  }

  private chunkArray(array: any[], size: number): any[][] {
    const result: any[][] = [];
    for (let i = 0; i < array.length; i += size) {
      result.push(array.slice(i, i + size));
    }
    return result;
  }

}